import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import type { Utterance } from "../../types";
import { UtteranceType } from "../../types/conversation";
import { renderWithProviders } from "../../tests/utils";
import { BotMessageInfo } from "./BotMessageInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

function baseUtterance(overrides: Partial<Utterance> = {}): Utterance {
  return {
    __typename: "Utterance",
    id: "u1",
    metadata: {
      parseData: {},
    },
    rephrase: false,
    rephrasePrompt: null,
    text: "Hello",
    timestamp: "2020-01-01T00:00:00.000Z",
    tokens: [],
    type: UtteranceType.Bot,
    originalTimestamp: 0,
    ...overrides,
  };
}

function renderBotMessageInfo(utterance: Utterance) {
  return renderWithProviders(<BotMessageInfo utterance={utterance} onClose={() => undefined} />);
}

describe("BotMessageInfo", () => {
  it("uses Agent response details as the panel title", () => {
    renderBotMessageInfo(baseUtterance());
    expect(screen.getByRole("heading", { name: /agent response details/i })).toBeInTheDocument();
  });

  describe("latency section", () => {
    it("shows latency accordion when execution_times is present", () => {
      const utterance = baseUtterance({
        metadata: {
          parseData: {},
          execution_times: { command_processor: 120, prediction_loop: 80 },
        },
      });

      renderBotMessageInfo(utterance);

      expect(screen.getByText("Latency per turn")).toBeInTheDocument();
    });

    it("shows latency pill from command_processor", () => {
      const utterance = baseUtterance({
        metadata: {
          parseData: {},
          execution_times: { command_processor: 120, prediction_loop: 80 },
        },
      });

      renderBotMessageInfo(utterance);

      expect(screen.getByText("~120 ms")).toBeInTheDocument();
    });

    it("does not show latency section when execution_times is absent", () => {
      renderBotMessageInfo(baseUtterance());

      expect(screen.queryByText("Latency per turn")).not.toBeInTheDocument();
    });
  });
});
